head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/calendar.js");
// 달력컨트롤을
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.spacYN = "N"; //기업인수목적 회사 구분
scwin.vScrenID = "ULDSTF05270.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    var url = "/invstcautnRemndIIssue.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=searchInvstcautnRemndIssue" + "&DIV_IDX=" + DIV_IDX_ICR_LIST_K + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + txb_IsurCd.getValue();
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_IsurCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_IsurNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
    scwin.fn_search();
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_IsurNm.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts_List.getCellData(dts_List.getRowPosition(), "RSN_CHG_TP_CD"); // 사유변동구분코드
    arrPar[6] = scwin.spacYN; //기업인수목적회사 구분_2010.05.30

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = txb_IsurCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_IsurNm.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 사유변동구분코드
    arrPar[6] = scwin.spacYN; //기업인수목적회사 구분_2010.05.30

};
scwin.fn_newpre_create_frame = async function(arg) {
    /*
    사유변동구분코드		
    1 : 지정	
    2 : 일부추가	
    3 : 일부해제	
    4 : 일부추가 및 일부해제	
    0 : 해제	
    */
    if (scwin.spacYN == "N") {
        switch (arg) {
            case "1":
                await $c.frame.CreateDialogFrame("DLG_0", "../lstproc/ULDSTF05271.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자주의환기종목지정", 200, 100, 615, 440 + 35, "window");
                break;
            case "2":
                await $c.frame.CreateDialogFrame("DLG_1", "../lstproc/ULDSTF05272.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자주의환기종목지정 사유추가", 200, 100, 615, 600 + 35, "window");
                break;
            case "3":
                await $c.frame.CreateDialogFrame("DLG_2", "../lstproc/ULDSTF05273.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자주의환기종목지정 사유 일부해제", 200, 100, 615, 600 + 35, "window");
                break;
            case "4":
                await $c.frame.CreateDialogFrame("DLG_3", "../lstproc/ULDSTF05274.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자주의환기종목지정 사유 추가 및 일부해제", 200, 100, 630, 700 + 35, "window");
                break;
            case "0":
                await $c.frame.CreateDialogFrame("DLG_4", "../lstproc/ULDSTF05275.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 투자주의환기종목지정 해제", 200, 100, 615, 615 + 35, "window");
                break;
        }
    } else {
        switch (arg) {
            case "1":
                await $c.frame.CreateDialogFrame("DLG_0", "../lstproc/ULDSTF05271.gfm", "기업인수목적회사 투자주의환기종목지정", 200, 100, 615, 440 + 35, "window");
                break;
            case "2":
                await $c.frame.CreateDialogFrame("DLG_1", "../lstproc/ULDSTF05272.gfm", "기업인수목적회사 투자주의환기종목지정 사유추가", 200, 100, 615, 600 + 35, "window");
                break;
            case "3":
                await $c.frame.CreateDialogFrame("DLG_2", "../lstproc/ULDSTF05273.gfm", "기업인수목적회사 투자주의환기종목지정 사유 일부해제", 200, 100, 615, 600 + 35, "window");
                break;
            case "4":
                await $c.frame.CreateDialogFrame("DLG_3", "../lstproc/ULDSTF05274.gfm", "기업인수목적회사 투자주의환기종목지정 사유 추가 및 일부해제", 200, 100, 630, 700 + 35, "window");
                break;
            case "0":
                await $c.frame.CreateDialogFrame("DLG_4", "../lstproc/ULDSTF05275.gfm", "기업인수목적회사 투자주의환기종목지정 해제", 200, 100, 615, 615 + 35, "window");
                break;
        }
    }
    scwin.fn_search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.img_Search_onclick = function() {
    if (txb_IsurCd.getValue() != "") {
        scwin.fn_search();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
    }
};
scwin.btn_IsuCdSearch_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;

    //기업인수목적 회사와 주권 목록을 나눔
    if (scwin.pMenuID == "STF05270") {
        $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
    } else if (scwin.pMenuID == "STF05276") {
        //기업인수목적 회사
        $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
        scwin.spacYN = "Y"; //기업인수목적 회사에 관련된 사유가 따로 마련되어 있지 않아서

    } else {
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    }

    //fn_PopFindCorpChrg(fr_SecuGrpId);

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_Close_onclick = function() {
    window.close();
};
scwin.img_Regist_onclick = function() {
    if (txb_IsurCd.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
        txb_IsurCd.focus();
        return true;
    }
    if (cmb_RegistTyp.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistTyp.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame(cmb_RegistTyp.BindColVal);
};
scwin.img_Excel_onclick = function() {
    if (dts_List.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "투자주의환기종목지정내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_List_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;

    // 지정업무구분코드 값 넘겨야함
    scwin.fn_newpre_create_frame(dts_List.getCellData(dts_List.getRowPosition(), "RSN_CHG_TP_CD"));
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
};
